/* Chapter 2 clinical case cards: single best answer. Source: Kaplan & Sadock's Synopsis of Psychiatry, 12th ed., Chapter 2. */
KS.add("ch02", "cases", [
  {"id":"c2-id01","tag":"ID","q":"A 9-year-old has a full-scale IQ of 62, but his adaptive skills in conceptual, social and practical domains are only mildly impaired. How is severity assigned under DSM-5?","choices":["By IQ: moderate","By IQ alone","Borderline intellectual functioning","Severity cannot be assigned","By adaptive functioning: mild"],"answer":4,"why":"DSM-5 grades severity by adaptive functioning across conceptual, social and practical domains, not IQ."},
  {"id":"c2-id02","tag":"ID","q":"A 7-year-old has IQ 76 with average adaptive skills. What is the DSM-5 status?","choices":["Unspecified intellectual disability","Borderline intellectual functioning, not a diagnosis","Mild intellectual disability","Moderate intellectual disability","Specific learning disorder by definition"],"answer":1,"why":"IQ 70–80 was formerly borderline intellectual functioning; in DSM-5 it is only a condition that may be a focus of attention."},
  {"id":"c2-id03","tag":"Workup","q":"A 4-year-old with developmental delay has microcephaly, hypertelorism, short stature and a family history of intellectual disability. Which test is most indicated?","choices":["Lead level only","EEG only","Chromosome analysis","Projective testing","No testing until school age"],"answer":2,"why":"Multiple anomalies with delay call for chromosome analysis; these features raise the yield for subtelomeric defects."},
  {"id":"c2-id04","tag":"Workup","q":"A 6-year-old with intellectual disability has begun to lose skills he had mastered. What is indicated?","choices":["IQ retest only","Reassurance","Neuroimaging","Behavior therapy alone","Stimulant trial"],"answer":2,"why":"Loss of previously acquired skills, seizures, abnormal head size or neurologic signs are indications for neuroimaging."},
  {"id":"c2-id05","tag":"Differential","q":"A 5-year-old raised in severe neglect tests in the intellectual disability range. After a year in a stimulating foster home, scores improve markedly. What best explains this?","choices":["Malingering","Delays from deprivation are partly reversible","Intellectual disability never improves","Testing error","A learning disorder"],"answer":1,"why":"Delays caused by maltreatment and neglect are partly reversible in an enriched environment."},
  {"id":"c2-id06","tag":"Genetics","q":"An adolescent boy with intellectual disability has a long face, large ears, hyperextensible joints, large testes, gaze avoidance and marked inattention. Which test confirms the likely diagnosis?","choices":["Karyotype for trisomy 21","Guthrie test","FMR1 testing for fragile X","Serum ceruloplasmin","Urine porphobilinogen"],"answer":2,"why":"These features fit fragile X syndrome, an FMR1 mutation at Xq27.3."},
  {"id":"c2-id07","tag":"Genetics","q":"A 2-year-old girl developed normally until about 1 year, then lost speech and purposeful hand use, began hand-wringing, and has hyperventilation spells while awake. Head growth has slowed. What is the diagnosis?","choices":["Selective mutism","Fragile X","Lesch–Nyhan","Childhood-onset schizophrenia","Rett syndrome"],"answer":4,"why":"Regression with hand-wringing, decelerating head growth and awake breathing irregularity in a girl is Rett syndrome."},
  {"id":"c2-id08","tag":"Genetics","q":"A boy with intellectual disability, choreoathetosis and spasticity repeatedly bites his lips and fingers. Which syndrome?","choices":["Down","Lesch–Nyhan","Cri-du-chat","Prader–Willi","Williams"],"answer":1,"why":"Lesch–Nyhan, an X-linked purine enzyme defect, produces severe compulsive self-biting."},
  {"id":"c2-id09","tag":"Genetics","q":"Parents of a child with Down syndrome ask about recurrence. The child's karyotype shows a 21;15 translocation. What is the key point?","choices":["Recurrence is impossible","Translocation means mosaicism","Only paternal age matters","Recurrence is the same as the general population","Translocation Down syndrome is often inherited, and recurrence risk is much higher"],"answer":4,"why":"Translocation Down syndrome is usually inherited from a carrier parent; the chapter cites a risk of about 1 in 3."},
  {"id":"c2-id10","tag":"Genetics","q":"A newborn screen is positive for phenylketonuria. What gives the best outcome?","choices":["Stimulants","Phenylalanine supplements","Wait for symptoms","Start a low-phenylalanine diet as early as possible, ideally before 3 months","Start diet at school age"],"answer":3,"why":"Early diagnosis and a low-phenylalanine diet before 6 months (best before 3) can preserve average intelligence; the diet continues indefinitely."},
  {"id":"c2-id11","tag":"Acquired","q":"A newborn has short palpebral fissures, a smooth philtrum, thin upper lip, microcephaly and a heart defect. Which preventable cause is most likely?","choices":["Prenatal cocaine","Fetal alcohol syndrome","Down syndrome","Congenital rubella","PKU"],"answer":1,"why":"These are the classic facial and growth features of fetal alcohol syndrome."},
  {"id":"c2-id12","tag":"Acquired","q":"An infant born to a mother who used heroin develops irritability, tremor, hypertonia, vomiting and a high-pitched cry on day 2. What is happening?","choices":["Meningitis is certain","Fetal alcohol syndrome","Cocaine intoxication","Neonatal opioid withdrawal","Normal newborn behavior"],"answer":3,"why":"Opioid withdrawal appears within the first 2 days; it can be life-threatening if untreated."},
  {"id":"c2-id13","tag":"Treatment","q":"A 10-year-old with mild intellectual disability and ADHD symptoms needs medication. Which is preferred?","choices":["A stimulant, with close monitoring for side effects","Lithium","Haloperidol","No treatment is effective","Risperidone"],"answer":0,"why":"Stimulants are preferred; children with intellectual disability benefit but have more side effects."},
  {"id":"c2-id14","tag":"Treatment","q":"A 12-year-old with moderate intellectual disability has severe aggression and self-injury despite behavioral treatment. Which medication has the best short-term evidence?","choices":["Carbamazepine as first choice","Risperidone or aripiprazole, used cautiously","Methylphenidate","Long-term benzodiazepines","Piracetam"],"answer":1,"why":"Risperidone and aripiprazole show moderate to large short-term effects; side effects argue for caution beyond an acute crisis."},
  {"id":"c2-id15","tag":"Services","q":"A 2-year-old has just been diagnosed with intellectual disability. Which plan structures his early intervention services?","choices":["Individualized Family Service Plan","IEP","Special Olympics","504 plan","Respite care plan"],"answer":0,"why":"Early intervention (birth to 3) uses an Individualized Family Service Plan; schools use an IEP from 3 to 21."},
  {"id":"c2-cm01","tag":"Language","q":"An 18-month-old says no words but points to familiar objects when named, follows simple commands, makes good eye contact and enjoys peek-a-boo. Hearing is normal. What fits best?","choices":["Mixed receptive–expressive deficits","Expressive language deficits","Intellectual disability","Autism spectrum disorder","Selective mutism"],"answer":1,"why":"Comprehension and social engagement are intact while expressive language lags: the expressive picture."},
  {"id":"c2-cm02","tag":"Language","q":"A 2-year-old does not point to everyday objects or follow simple commands and responds to a door slam but not to her name being spoken. Motor and play skills are normal. What is the next step?","choices":["Diagnose selective mutism","Start a stimulant","Audiogram and comprehensive speech-language evaluation","MRI first","Reassure that she will catch up"],"answer":2,"why":"Possible mixed receptive–expressive deficits; hearing must be checked with an audiogram, then standardized receptive and expressive testing."},
  {"id":"c2-cm03","tag":"Language","q":"Parents of a healthy 2½-year-old 'late talker' with normal comprehension ask whether therapy should start now. What does the chapter suggest?","choices":["Refer for genetic testing","Many such children catch up; treatment is usually started if the delay persists past the preschool years","Start an SSRI","Therapy is never helpful","Immediate intensive therapy is essential"],"answer":1,"why":"50–80% of late talkers catch up and early intervention effects are modest, so expressive treatment usually begins if delays persist."},
  {"id":"c2-cm04","tag":"Speech","q":"A 6-year-old says 'wabbit' for rabbit and 'fum' for thumb; language and hearing are normal. What type of error is this?","choices":["Omission","Distortion","Addition","Dysarthria","Substitution"],"answer":4,"why":"Replacing one phoneme with another is a substitution, the middle level of severity."},
  {"id":"c2-cm05","tag":"Speech","q":"A child with unclear speech drools, chews and swallows abnormally, and speaks slowly with poor tongue movement. What is most likely?","choices":["Speech sound disorder","Cluttering","Social (pragmatic) communication disorder","Dysarthria","Stuttering"],"answer":3,"why":"These signs point to dysarthria from a structural or neurologic cause, which is excluded from speech sound disorder and remits less often."},
  {"id":"c2-cm06","tag":"Speech","q":"A 9-year-old still distorts r and l. When is spontaneous recovery unlikely, and what follows?","choices":["Recovery is likely until 15; wait","Only surgery helps","Spontaneous recovery is rare after 8, so speech therapy is indicated","Medication is first line","Speech sound disorder always persists"],"answer":2,"why":"Most outgrow it by third grade; recovery is rare after age 8, so persistent errors should be treated."},
  {"id":"c2-cm07","tag":"Stuttering","q":"A 4-year-old has repetitions and prolongations, looks tense when speaking, and blinks during blocks. Which treatment is evidence based and delivered by parents?","choices":["Haloperidol","Lidcombe Program","Psychoanalysis","Delayed auditory feedback","Waiting until adolescence"],"answer":1,"why":"The Lidcombe Program is an operant, parent-delivered program supervised by a speech therapist; early intervention greatly improves resolution."},
  {"id":"c2-cm08","tag":"Stuttering","q":"A 24-year-old who has stuttered since childhood avoids phone calls and meetings, substitutes words and fears speaking. What comorbidity should be assessed?","choices":["Social anxiety disorder","Dementia","Schizophrenia","ADHD only","Conversion disorder"],"answer":0,"why":"40–60% of adults with persistent stuttering have social anxiety disorder; CBT or an SSRI may be added."},
  {"id":"c2-cm09","tag":"Stuttering","q":"A boy speaks in rapid, jerky spurts that are hard to follow but seems unaware of any problem. What is this?","choices":["Stuttering","Expressive language disorder","Cluttering","Selective mutism","Dysarthria"],"answer":2,"why":"Cluttering is erratic, dysrhythmic speech with little awareness; stutterers become aware of their difficulty."},
  {"id":"c2-cm10","tag":"Pragmatic","q":"A 9-year-old with good vocabulary and grammar misses jokes, talks to toddlers as to adults, interrupts and ignores cues to change topic. There has never been any repetitive behavior or restricted interest. What is the diagnosis?","choices":["Social anxiety disorder","Social (pragmatic) communication disorder","Autism spectrum disorder","Language disorder","ADHD only"],"answer":1,"why":"Social communication deficits without any history of restricted, repetitive behaviors define social (pragmatic) communication disorder."},
  {"id":"c2-cm11","tag":"Pragmatic","q":"The same picture is seen in a 10-year-old whose parents report intense lining up of toys and rigid routines at age 3. Which diagnosis applies?","choices":["No diagnosis","OCD","Social (pragmatic) communication disorder","Autism spectrum disorder","Stereotypic movement disorder"],"answer":3,"why":"If restricted, repetitive behaviors are present in the history, autism spectrum disorder is diagnosed even if they are no longer visible."},
  {"id":"c2-as01","tag":"ASD","q":"A 24-month-old has no words, little interest in other children, plays with toy cars by spinning their wheels for long periods, and tantrums when his route to daycare changes. Hearing is normal. What is the most likely diagnosis?","choices":["Language disorder","Reactive attachment disorder","Selective mutism","Autism spectrum disorder","Social (pragmatic) communication disorder"],"answer":3,"why":"Social communication deficits plus restricted, repetitive play and insistence on sameness define ASD."},
  {"id":"c2-as02","tag":"ASD","q":"A 10-month-old babbled normally until about 7 months, then gradually stopped. She looks toward people, gestures and seeks interaction, and startles only to very loud noises. What is the key next step?","choices":["Risperidone","MRI for regression","Start ABA for autism","Reassure","Audiogram or auditory evoked potentials"],"answer":4,"why":"Normal babbling that fades, preserved social seeking and response only to loud sounds suggest deafness; hearing must be tested."},
  {"id":"c2-as03","tag":"ASD","q":"A 4-year-old with ASD speaks fluently in long scripts from cartoons, repeats questions back and says 'you want juice' when he wants juice. What does this illustrate?","choices":["Echolalia and pronoun reversal","Cluttering","Thought disorder","Selective mutism","Stuttering"],"answer":0,"why":"Immediate and delayed echolalia and pronoun reversal are associated language features of ASD."},
  {"id":"c2-as04","tag":"Differential","q":"An 11-year-old with previously normal development and friends begins hearing voices, becomes suspicious and his schoolwork collapses. What is the most likely diagnosis?","choices":["Language disorder","Childhood-onset schizophrenia","Intellectual disability","Asperger disorder","Autism spectrum disorder"],"answer":1,"why":"Hallucinations and delusions with deterioration from a normal baseline point to schizophrenia; ASD begins in the early developmental period."},
  {"id":"c2-as05","tag":"Treatment","q":"A 9-year-old with ASD has daily severe tantrums, aggression and head banging despite behavioral treatment. Which medication is first line?","choices":["Fenfluramine","Naltrexone","Risperidone","Fluoxetine","Secretin"],"answer":2,"why":"Risperidone (and aripiprazole) are FDA approved for irritability in ASD; risperidone is first line."},
  {"id":"c2-as06","tag":"Treatment","q":"After 6 months of good response, risperidone is stopped in a child with ASD. What is likely?","choices":["Rapid return of irritability","Sustained remission","Tardive dyskinesia within days","Improvement in core social deficits","Emergence of psychosis"],"answer":0,"why":"Continuation studies found persistent benefit but rapid return of symptoms in good responders after discontinuation."},
  {"id":"c2-as07","tag":"Treatment","q":"A 7-year-old with ASD has marked hyperactivity and inattention. Methylphenidate is started. What should the family expect compared with children who have ADHD alone?","choices":["Worsening of core autism","Greater benefit and fewer side effects","Moderate benefit with more frequent side effects such as irritability","Need for doses above 2 mg/kg","No benefit"],"answer":2,"why":"Methylphenidate is moderately effective in ASD, less so than in ADHD alone, with more side effects, including irritability."},
  {"id":"c2-as08","tag":"Treatment","q":"Parents ask about a supplement trial for their child's autism. Which has been shown ineffective in randomized trials?","choices":["Music therapy","Risperidone for irritability","Secretin","Melatonin for sleep onset","Social skills groups"],"answer":2,"why":"Secretin was ineffective in RCTs; melatonin reduces sleep-onset latency."},
  {"id":"c2-as09","tag":"Treatment","q":"A 3-year-old with ASD will start an intervention delivered in daycare and at home, built into play and daily routines, with parents as co-therapists. Which model is this?","choices":["Exposure and response prevention","Early Start Denver Model","Parent–child interaction therapy for stuttering","Lidcombe","TEACCH"],"answer":1,"why":"The Early Start Denver Model is naturalistic, ABA-informed and parent-involved for very young children."},
  {"id":"c2-as10","tag":"Prognosis","q":"Which child with ASD has the best prognosis?","choices":["IQ 55, no speech at 7","IQ 80 with no speech at 8","Any child with hyperlexia","IQ 40 with seizures","IQ 95, communicative language by age 5, average adaptive skills"],"answer":4,"why":"IQ above 70, average adaptive skills and communicative language by 5–7 predict the best outcome."},
  {"id":"c2-ad01","tag":"ADHD","q":"An 8-year-old is restless, blurts answers and loses things at school, but his parents report calm, focused behavior at home. Teacher ratings are high; parent ratings are normal. What is needed before diagnosing ADHD?","choices":["An MRI","A trial of stimulant","Evidence of impairing symptoms in at least two settings","Nothing; teacher report is enough","An EEG"],"answer":2,"why":"ADHD requires impairing symptoms in two or more settings; discrepant reports call for more information and other explanations."},
  {"id":"c2-ad02","tag":"ADHD","q":"A 7-year-old 'daydreamer' has brief staring spells many times a day with eyelid flutter and no memory of them. What is the best next step?","choices":["Atomoxetine","Reassurance","Neurology consultation and EEG","Start methylphenidate","Behavior therapy only"],"answer":2,"why":"Possible absence (petit mal) seizures can mimic inattention and require EEG and neurologic consultation."},
  {"id":"c2-ad03","tag":"ADHD","q":"Before starting a stimulant, a 10-year-old's history reveals fainting during soccer and an uncle who died suddenly at 30. What is appropriate?","choices":["No concern","Cardiology consultation and examination before stimulants","Start a tricyclic","Start a stimulant at low dose","Start guanfacine instead without evaluation"],"answer":1,"why":"Syncope and family sudden death are cardiac risk factors calling for cardiology evaluation; stimulants should not be used with known cardiac abnormalities."},
  {"id":"c2-ad04","tag":"Treatment","q":"A 9-year-old with ADHD and a chronic motor tic has worse tics on methylphenidate. Which alternative is often preferred?","choices":["Bupropion 450 mg","Desipramine","Higher stimulant dose","Extended-release guanfacine or clonidine","Haloperidol first line"],"answer":3,"why":"α2-agonists are sometimes preferred when stimulants exacerbate tics."},
  {"id":"c2-ad05","tag":"Treatment","q":"A girl starts atomoxetine while also taking fluoxetine. What interaction is expected?","choices":["Lower atomoxetine levels","Lithium toxicity","No interaction","Higher atomoxetine levels via CYP2D6 inhibition","Serotonin syndrome is certain"],"answer":3,"why":"Atomoxetine is a CYP2D6 substrate; fluoxetine, paroxetine and quinidine raise levels, and combined use raised BP and pulse more."},
  {"id":"c2-ad06","tag":"Treatment","q":"Parents of a boy starting atomoxetine ask about warnings. Which is correct?","choices":["Black-box for agranulocytosis","Contraindicated under 12","No warnings","Requires weekly blood counts","Black-box warning for suicidal thoughts and behavior; monitor like antidepressants"],"answer":4,"why":"Atomoxetine carries a black-box warning for suicidality, unlike stimulants."},
  {"id":"c2-ad07","tag":"Treatment","q":"A child on a stimulant for 3 years has slowed height gain. What does the chapter suggest?","choices":["Switch to a tricyclic","Consider drug holidays on weekends or summers, which allow catch-up growth","Add growth hormone","Ignore it","Stop all treatment permanently"],"answer":1,"why":"Continuous long-term use can suppress growth by a few centimeters; drug holidays allow eating and catch-up growth."},
  {"id":"c2-ad08","tag":"Treatment","q":"Which antidepressant should not be used for ADHD because of reported sudden deaths in children?","choices":["Desipramine","Bupropion","Fluoxetine","Atomoxetine","Venlafaxine"],"answer":0,"why":"Sudden deaths in children taking desipramine make tricyclics an unlikely choice for ADHD."},
  {"id":"c2-ad09","tag":"MTA","q":"In the MTA study, which approach was superior for oppositional symptoms, anxiety, social skills, parent–child relationships and reading?","choices":["Behavior therapy alone","No difference among groups","Combined medication and behavior therapy","Community care","Medication management alone"],"answer":2,"why":"Combined treatment, but not medication alone, was superior on these broader outcomes and used lower doses."},
  {"id":"c2-ad10","tag":"Adult","q":"A 26-year-old has lifelong distractibility, forgetfulness and restlessness, with school records of careless mistakes and talking out of turn, and no discrete mood episodes. He has no cardiac history. Which treatment is FDA approved for adults?","choices":["Short-acting methylphenidate only","Clonidine IR","Modafinil","Desipramine","A long-acting stimulant"],"answer":4,"why":"Only long-acting stimulants are FDA approved for adult ADHD."},
  {"id":"c2-ad11","tag":"Differential","q":"A 15-year-old with 'ADHD' has had three distinct weeks of little sleep, grandiosity and pressured speech, with normal periods between. What is most likely?","choices":["ADHD alone","Anxiety disorder","Learning disorder","Conduct disorder","A bipolar disorder (possibly comorbid with ADHD)"],"answer":4,"why":"Discrete episodes that wax and wane point to a mood disorder; ADHD symptoms are persistent."},
  {"id":"c2-ld01","tag":"SLD","q":"A 9-year-old with average IQ reads slowly with many omissions and substitutions, spells poorly, and avoids reading. Hearing and vision are normal and schooling has been adequate. What is the diagnosis?","choices":["Visual processing disorder","Language disorder only","ADHD, inattentive","Specific learning disorder with impairment in reading","Intellectual disability"],"answer":3,"why":"Slow, inaccurate reading and poor spelling well below age, without other explanations, define the reading specifier."},
  {"id":"c2-ld02","tag":"SLD","q":"Parents ask whether colored lenses will cure their son's dyslexia. What is accurate?","choices":["Yes; dyslexia is a visual problem","No; dyslexia reflects speech sound processing deficits, and visual-motor theories are unsupported","Only allergy treatment helps","Cerebellar exercises are first line","Medication cures dyslexia"],"answer":1,"why":"Visual-motor (scotopic sensitivity), allergy and cerebellar-vestibular theories are myths; the core deficit is phonologic."},
  {"id":"c2-ld03","tag":"Treatment","q":"Which approach to reading remediation is supported by the chapter?","choices":["Waiting for maturation","Projective testing","Explicit teaching of letter–sound associations, then syllables and words","Stimulant medication alone","Vision therapy"],"answer":2,"why":"Effective programs (e.g., Orton-Gillingham, DISTAR) begin with letter–sound associations and build to words."},
  {"id":"c2-ld04","tag":"Differential","q":"A 10-year-old is struggling in reading, math and writing. His adaptive skills and overall development are also delayed. What should be done first?","choices":["Assume ADHD","Diagnose three learning disorders","Vision therapy","Intellectual testing to separate global from specific deficits","Start a stimulant"],"answer":3,"why":"Intellectual disability lowers most skills; IQ testing distinguishes global from specific deficits."},
  {"id":"c2-ld05","tag":"Writing","q":"An 11-year-old participates well orally and reads and calculates at grade level, but his written work is sparse, misspelled and unpunctuated. He has no ADHD or mood disorder. Which recommendation fits?","choices":["No intervention","Stimulant medication","Speech therapy for stuttering","Accommodations (extra time, software) and specific writing instruction","Retain him a grade"],"answer":3,"why":"Specific learning disorder with impairment in written expression calls for accommodations and direct writing instruction."},
  {"id":"c2-ld06","tag":"Math","q":"A girl with ADHD treated well with a stimulant now freezes during math questions, feels shaky and has failed math. What should be added?","choices":["Antipsychotic","Higher stimulant dose only","Math remediation and attention to math anxiety","Drop math entirely","Reading tutoring only"],"answer":2,"why":"Persistent math impairment plus anxiety needs targeted math remediation and anxiety strategies alongside ADHD treatment."},
  {"id":"c2-mo01","tag":"DCD","q":"A 7-year-old cannot ride a bike, ties laces with difficulty and writes illegibly. Neurologic exam and strength are normal; IQ is average. What is the diagnosis?","choices":["Tourette disorder","Stereotypic movement disorder","Cerebral palsy","Muscular dystrophy","Developmental coordination disorder"],"answer":4,"why":"Coordination well below age with normal neurologic findings and intellect is developmental coordination disorder."},
  {"id":"c2-mo02","tag":"Stereotypic","q":"A 3-year-old with typical development rocks rhythmically before sleep and when tired, seems soothed by it, and can be distracted out of it. There is no injury. What is the best approach?","choices":["Reassure; transient rhythmic habits are common and usually fade by about 4","Diagnose Tourette disorder","Start risperidone","MRI","Physical restraint"],"answer":0,"why":"60–80% of toddlers show transient comforting rhythmic activities that disappear by about age 4; isolated stereotypies may not need medication."},
  {"id":"c2-mo03","tag":"Stereotypic","q":"A boy with severe intellectual disability bangs his head and bites his hands, causing injury. Which behavioral approach has the best support?","choices":["Ignoring the behavior","Psychoanalysis","Exposure to loud noise","Habit reversal and differential reinforcement of other behavior","Bed rest"],"answer":3,"why":"Habit reversal and differential reinforcement are the most promising behavioral treatments; medication is added for dangerous self-injury."},
  {"id":"c2-mo04","tag":"Tourette","q":"A 9-year-old has had eye blinking, head jerks and shoulder shrugs for 2 years and, for the past 6 months, frequent throat clearing and sniffing. He feels an urge before each. What is the diagnosis?","choices":["Sydenham chorea","Persistent motor tic disorder","OCD","Stereotypic movement disorder","Tourette disorder"],"answer":4,"why":"Multiple motor tics plus at least one vocal tic, lasting more than a year with onset before 18, meet Tourette criteria; they need not be concurrent."},
  {"id":"c2-mo05","tag":"Tourette","q":"Parents of a 10-year-old with moderate Tourette disorder and teasing at school ask about first-line treatment. What is recommended?","choices":["Biofeedback alone","Habit reversal (CBIT) with psychoeducation","Relaxation training alone","Clozapine","Haloperidol immediately"],"answer":1,"why":"Habit reversal (awareness training plus competing response) is first-line behavioral treatment; relaxation and biofeedback alone are not effective."},
  {"id":"c2-mo06","tag":"Tourette","q":"A child with ADHD and mild tics is doing well on methylphenidate. The parents worry the stimulant will worsen the tics. What does the chapter say?","choices":["Add clozapine","Tics prove the ADHD diagnosis was wrong","Switch to haloperidol","In most children with ADHD and tics, methylphenidate does not increase tics; monitor","Stimulants always worsen tics; stop now"],"answer":3,"why":"Data suggest methylphenidate does not increase tic rate or intensity in most children with hyperactivity and tics, though tics should be watched."},
  {"id":"c2-mo07","tag":"Tourette","q":"An adolescent with severe Tourette disorder and obsessive-compulsive symptoms needs medication after behavioral therapy. Which is best supported?","choices":["Desipramine","Fluoxetine alone as tic treatment","Clozapine","Risperidone","Lamotrigine"],"answer":3,"why":"Risperidone has the strongest evidence and also reduced obsessive-compulsive symptoms better than pimozide in one study; clozapine is not useful for tics."},
  {"id":"c2-mo08","tag":"Tourette","q":"A child with Tourette disorder and ADHD needs one medication for both. Which fits?","choices":["Lithium","Pimozide","Clonidine or guanfacine","Clozapine","Haloperidol"],"answer":2,"why":"α2-agonists (and atomoxetine) are used as primary or adjunctive treatment for comorbid ADHD and tics."},
  {"id":"c2-mo09","tag":"Chronic tic","q":"A 7-year-old has had only facial blinking and grimacing tics for 14 months, with no vocal tics. What is the diagnosis and outlook?","choices":["Persistent (chronic) motor tic disorder; onset at 6–8 with facial tics predicts good outcome","Stereotypic movement disorder","Transient tic disorder","Tourette disorder; lifelong","Huntington disease"],"answer":0,"why":"Motor tics only for more than a year is persistent motor tic disorder; onset at 6–8 and facial tics carry the best prognosis."},
  {"id":"c2-fe01","tag":"Pica","q":"A 3-year-old in an old apartment repeatedly eats paint chips and plaster and now has abdominal pain and irritability. What is the first priority?","choices":["Psychodynamic therapy","Start an SSRI","Reassure; it is normal mouthing","Check lead and remove the child from lead exposure","Antipsychotic"],"answer":3,"why":"Lead poisoning must be identified and the exposure eliminated before behavioral treatment of pica."},
  {"id":"c2-fe02","tag":"Pica","q":"A pregnant woman eats laundry starch daily, a practice not part of her culture. Which deficiency should be checked?","choices":["Vitamin A","Vitamin C","Iodine","Iron","Copper"],"answer":3,"why":"Large starch ingestion is associated with severe iron deficiency; pregnancy pica usually resolves after delivery."},
  {"id":"c2-fe03","tag":"Rumination","q":"A 7-month-old repeatedly brings up milk after feeds without retching, arching her back and appearing content, then re-swallows. Weight is normal. Pyloric stenosis has been excluded. What is the diagnosis and first approach?","choices":["ARFID; tube feeding","Rumination disorder; education and habit reversal with nurturing engagement","Pica; lead level","Normal spitting up; no action","GERD only; PPI"],"answer":1,"why":"Effortless, pleasurable regurgitation for a month or more is rumination; habit reversal and nurturing engagement are recommended."},
  {"id":"c2-fe04","tag":"ARFID","q":"A 9-year-old eats only five bland foods because other textures make him gag. He is underweight and taking supplements. He has no concern about weight or shape. What is the diagnosis?","choices":["Pica","OCD","Avoidant/restrictive food intake disorder","Rumination disorder","Anorexia nervosa"],"answer":2,"why":"Sensory-based avoidance causing low weight and supplement dependence, without body-image disturbance, is ARFID."},
  {"id":"c2-fe05","tag":"ARFID","q":"An infant with a 'difficult' temperament eats irregularly and refuses food. Which advice fits the transactional model?","choices":["Offer food constantly","Feed at regular 3–4 hour intervals, water only between, praise self-feeding, limit distractions","Reward with sweets","Force-feed until intake is adequate","Start risperidone"],"answer":1,"why":"The transactional model promotes internal regulation with regular meals, praise for self-feeding and calm attention to positive behavior."},
  {"id":"c2-tr01","tag":"Attachment","q":"A 2-year-old removed from severe neglect rarely seeks comfort when hurt, shows little positive emotion and is watchful and sad with foster parents. She is not autistic. What is the diagnosis?","choices":["Selective mutism","Separation anxiety disorder","Disinhibited social engagement disorder","Reactive attachment disorder","Autism spectrum disorder"],"answer":3,"why":"An emotionally withdrawn, inhibited pattern after pathogenic care is reactive attachment disorder."},
  {"id":"c2-tr02","tag":"Attachment","q":"A 6-year-old adopted from an orphanage at 4 hugs strangers, wanders off with unfamiliar adults and never checks back with his parents. Impulsivity alone does not explain it. What is the diagnosis?","choices":["ADHD","Disinhibited social engagement disorder","Reactive attachment disorder","Conduct disorder","Bipolar disorder"],"answer":1,"why":"Indiscriminate overfamiliarity with strangers after institutional care is disinhibited social engagement disorder."},
  {"id":"c2-tr03","tag":"Attachment","q":"An 8-month-old is below the 3rd percentile for weight with normal head circumference, apathetic and listless, in a home with suspected neglect. Growth hormone is normal. What is the first step?","choices":["Start an SSRI","Genetic testing first","Growth hormone therapy","Outpatient play therapy only","Ensure safety: report suspected neglect and hospitalize for nutrition"],"answer":4,"why":"Safety and nutrition come first; neglect must be reported, and malnourished children need hospitalization, where weight usually rises quickly."},
  {"id":"c2-tr04","tag":"PTSD","q":"Four months after a car crash, a 5-year-old repeatedly crashes toy cars together, has nightmares, refuses car rides and has lost interest in play. What is the diagnosis and first-line treatment?","choices":["Acute stress disorder; benzodiazepine","Normal reaction; no treatment","ODD; parent training","ADHD; stimulant","PTSD; trauma-focused CBT"],"answer":4,"why":"Posttraumatic play, nightmares, avoidance and loss of interest beyond 1 month are PTSD; TF-CBT has the best evidence."},
  {"id":"c2-tr05","tag":"PTSD","q":"A 12-year-old has nightmares, avoidance and hypervigilance for 10 days after a shooting at school. What is the diagnosis?","choices":["PTSD","Delayed-onset PTSD","Acute stress disorder","Generalized anxiety disorder","Adjustment disorder only"],"answer":2,"why":"Full symptoms lasting at least 3 days but under 1 month are acute stress disorder."},
  {"id":"c2-tr06","tag":"PTSD","q":"A family asks whether sertraline alone will treat their 10-year-old's PTSD. What does the evidence show?","choices":["Benzodiazepines are proven better","In youth, sertraline did not beat placebo for core PTSD symptoms; TF-CBT is the mainstay","Medication is never used","Antipsychotics are first line","Sertraline is FDA approved for pediatric PTSD"],"answer":1,"why":"Pediatric trials of sertraline and citalopram were negative for core symptoms; TF-CBT is first line, with SSRIs used for comorbid depression and anxiety."},
  {"id":"c2-tr07","tag":"PTSD","q":"A school wants an evidence-based group program for students with trauma symptoms after community violence. Which fits?","choices":["ESDM","CBITS","MTA protocol","TEACCH","Lidcombe"],"answer":1,"why":"Cognitive-Behavioral Intervention for Trauma in Schools delivers group and individual exposure-based work in school with strong results."},
  {"id":"c2-dp01","tag":"Depression","q":"An 8-year-old has had 6 weeks of stomachaches, irritability, tantrums, poor sleep and loss of interest in play. He hears a voice saying he is bad. What is most likely?","choices":["Major depressive disorder with mood-congruent psychotic features","Separation anxiety disorder","ADHD","Childhood-onset schizophrenia","Normal behavior"],"answer":0,"why":"Somatic complaints, irritability and mood-congruent hallucinations are typical of prepubertal major depression."},
  {"id":"c2-dp02","tag":"Depression","q":"A 15-year-old with moderate–severe depression and passive suicidal thoughts is assessed as safe for outpatient care. Which treatment had the best 12-week response in TADS?","choices":["Tricyclic","CBT alone","Placebo","Supportive therapy","Fluoxetine plus CBT"],"answer":4,"why":"Combined fluoxetine and CBT had the highest response (71%) and adding CBT reduced suicidal ideation."},
  {"id":"c2-dp03","tag":"Depression","q":"A 16-year-old did not respond to 8 weeks of an adequate fluoxetine dose. What does TORDIA support?","choices":["Stop treatment","ECT immediately","Switch to another SSRI and add CBT","Switch to a tricyclic","Add an antipsychotic first"],"answer":2,"why":"In TORDIA, switching medication plus CBT gave higher response; the second drug class made no difference."},
  {"id":"c2-dp04","tag":"Depression","q":"Two weeks after starting sertraline, a 13-year-old becomes talkative, restless and sleeps 4 hours, with no prior mood episodes. What is the best step?","choices":["Ignore","Add a stimulant","Increase sertraline","Diagnose bipolar I and start lithium for life","Stop the SSRI and observe; activation does not by itself prove bipolar disorder"],"answer":4,"why":"Behavioral activation or hypomania on an SSRI calls for discontinuation; it does not necessarily predict bipolar disorder."},
  {"id":"c2-dp05","tag":"Depression","q":"A 12-year-old has been irritable and low most days for 14 months, with poor self-esteem and low energy and no periods of relief longer than a month. No mania. What is the diagnosis?","choices":["DMDD","Persistent depressive disorder","Major depressive disorder","Adjustment disorder","Cyclothymia"],"answer":1,"why":"In youth, persistent depressive disorder requires depressed or irritable mood for 1 year with two or more symptoms."},
  {"id":"c2-dp06","tag":"Depression","q":"A depressed adolescent responded well to an SSRI 3 months ago. How long should treatment continue?","choices":["Lifelong","Until age 25","Stop now","About 1 year after response, then taper during a low-stress period","2 weeks after remission"],"answer":3,"why":"Recommendations are to continue for 1 year after a good response, then discontinue at a time of relatively low stress."},
  {"id":"c2-dp07","tag":"Suicide","q":"A 16-year-old boy with depression, alcohol use and fights at school took an overdose yesterday and now says he is 'fine.' What is appropriate?","choices":["Hospitalize until acute suicidality resolves","No intervention needed","Outpatient follow-up in a month","Start fluoxetine and send home","Discharge with a hotline number"],"answer":0,"why":"Male over 12 with aggression, substance use and a recent attempt is high risk; hospitalization is indicated."},
  {"id":"c2-dp08","tag":"Suicide","q":"Parents of a depressed 14-year-old say they would know if their son were suicidal. What is the evidence-based response?","choices":["Ask only the parents","Caregivers are often unaware, so the adolescent must be asked directly","Avoid the topic to prevent suggestion","Use projective tests instead","Agree; parents always know"],"answer":1,"why":"Studies consistently show caregivers are often unaware of suicidal thoughts; direct questioning of the youth is necessary."},
  {"id":"c2-dp09","tag":"Suicide","q":"Which single change at home most reduces an impulsive adolescent's suicide risk according to the chapter's risk profile?","choices":["Changing schools","Removing access to loaded guns","Less contact with peers","Stricter discipline","More homework"],"answer":1,"why":"Access to loaded guns at home is a major factor in adolescent suicide; firearms are the leading method."},
  {"id":"c2-bp01","tag":"Bipolar","q":"A 16-year-old with a depressed mother and bipolar uncle develops 10 days of no sleep, grandiosity, believing he is chosen by God, and racing thoughts. What is the diagnosis and first-line class of medication?","choices":["Schizophrenia; clozapine","ADHD; stimulant","DMDD; SSRI","Bipolar I with psychotic features; an atypical antipsychotic","Conduct disorder; parent training"],"answer":3,"why":"A discrete manic episode with psychosis is bipolar I; atypical antipsychotics act faster and more robustly than mood stabilizers in youth."},
  {"id":"c2-bp02","tag":"DMDD","q":"A 9-year-old has had near-daily rages at home and school for 18 months and is irritable most of the time in between. No discrete manic episodes. What is the diagnosis?","choices":["ODD only","Major depressive disorder","Disruptive mood dysregulation disorder","Intermittent explosive disorder","Bipolar I disorder"],"answer":2,"why":"Frequent outbursts plus persistent irritability for over a year in two settings, beginning before 10, is DMDD."},
  {"id":"c2-bp03","tag":"DMDD","q":"Parents of a 10-year-old with DMDD ask whether he will become bipolar. What is accurate?","choices":["He will develop schizophrenia","Longitudinal data show higher risk of depression and anxiety rather than bipolar disorder","He will outgrow it by 12","Only if he takes stimulants","Yes, nearly all do"],"answer":1,"why":"Chronic irritability and severe mood dysregulation predict later unipolar depression and anxiety disorders."},
  {"id":"c2-bp04","tag":"DMDD","q":"A 7-year-old argues, defies rules and deliberately annoys his parents only at home, with tantrums but normal mood between them. What fits?","choices":["Bipolar II","ODD","DMDD","Conduct disorder","MDD"],"answer":1,"why":"Defiance and annoyance limited to one setting, without persistent irritable mood between outbursts, fits ODD rather than DMDD."},
  {"id":"c2-bp05","tag":"Bipolar","q":"A 14-year-old with bipolar disorder has stabilized on medication. Which psychosocial treatment reduces relapse?","choices":["Family-focused treatment","Habit reversal","Exposure and response prevention","Lidcombe Program","TEACCH"],"answer":0,"why":"Family-focused psychoeducation, mood management, communication and problem-solving training reduce relapse."},
  {"id":"c2-dc01","tag":"ODD","q":"A 7-year-old argues with his parents daily, refuses chores, deliberately annoys his sister, blames others and loses his temper, for 8 months, but is cooperative at school and has never hurt anyone or stolen. What is the diagnosis and severity?","choices":["DMDD","Conduct disorder, mild","ODD, mild (one setting)","Normal behavior","ADHD"],"answer":2,"why":"Four or more ODD symptoms for 6 months in one setting without violating others' rights is ODD, mild."},
  {"id":"c2-dc02","tag":"ODD","q":"Which is the primary treatment for a 6-year-old with ODD?","choices":["Individual psychoanalysis","Risperidone","Stimulant","Parent management training (e.g., PCIT)","Residential placement"],"answer":3,"why":"Family intervention with parent training, reinforcing positive and ignoring oppositional behavior, is primary."},
  {"id":"c2-dc03","tag":"CD","q":"A 12-year-old has shoplifted repeatedly since 8, set fires at 6, starts fights, is cruel to his brother and has been truant this year. What is the diagnosis and onset type?","choices":["Conduct disorder, childhood-onset","DMDD","ODD","Antisocial personality disorder","Conduct disorder, adolescent-onset"],"answer":0,"why":"Multiple rights-violating behaviors with symptoms before 10 indicate childhood-onset conduct disorder."},
  {"id":"c2-dc04","tag":"CD","q":"A 15-year-old with conduct disorder shows no remorse after hurting a peer, does not care about grades and has shallow affect. Which specifier applies?","choices":["With psychotic features","Adolescent-onset only","With limited prosocial emotions","In remission","Mild"],"answer":2,"why":"Two or more of lack of remorse, callousness, unconcern about performance and shallow affect define this specifier."},
  {"id":"c2-dc05","tag":"CD","q":"A 19-year-old with conduct problems since age 11 now meets criteria for antisocial personality disorder. What is diagnosed?","choices":["Neither","Both","ODD","Conduct disorder","Antisocial personality disorder"],"answer":4,"why":"Conduct disorder after 18 is diagnosed only if antisocial personality disorder criteria are not met."},
  {"id":"c2-dc06","tag":"CD","q":"Parents want harsher physical punishment for their 11-year-old with conduct disorder. What does the chapter say?","choices":["Only physical punishment helps girls","It prevents substance use","Severe punishment cures CD","It has no effect","Severe punishment usually increases rage and maladaptive behavior"],"answer":4,"why":"Harsh punitive parenting is a risk factor, and severe punishment almost always worsens rage and frustration."},
  {"id":"c2-dc07","tag":"CD","q":"Which medication has the best evidence for aggression in youth with disruptive behavior disorders?","choices":["Fluoxetine","Carbamazepine","Risperidone","Lithium for all","Lorazepam"],"answer":2,"why":"Placebo-controlled trials support risperidone; carbamazepine failed in a controlled trial."},
  {"id":"c2-ax01","tag":"Anxiety","q":"A 9-year-old has refused school for 5 weeks, fears his mother will die in an accident, will not sleep alone, has nightmares of losing her and complains of stomachaches on school mornings. What is the diagnosis?","choices":["Major depression","Separation anxiety disorder","Panic disorder","Social anxiety disorder","Generalized anxiety disorder"],"answer":1,"why":"Three or more separation-focused symptoms for at least 4 weeks define separation anxiety disorder."},
  {"id":"c2-ax02","tag":"Anxiety","q":"What is the best management of this child's school refusal?","choices":["Change schools","Benzodiazepine every morning","Firm encouragement with a graded return to school, family involvement and exposure-based CBT","Home schooling until anxiety resolves","Wait for spontaneous remission"],"answer":2,"why":"School refusal with separation anxiety is an emergency; firm, supported, graded return and CBT are the core."},
  {"id":"c2-ax03","tag":"Anxiety","q":"A 13-year-old worries for hours daily about health, catastrophes, grades and family finances, seeks constant reassurance, has stomachaches and trouble falling asleep. What is the diagnosis?","choices":["Somatic symptom disorder","OCD","Social anxiety disorder","Generalized anxiety disorder","Separation anxiety disorder"],"answer":3,"why":"Excessive worry across many areas with physical symptoms for months is generalized anxiety disorder."},
  {"id":"c2-ax04","tag":"Anxiety","q":"A 15-year-old with severe social and generalized anxiety and depression is barely leaving home. Based on CAMS, what treatment gives the highest response?","choices":["Propranolol","Buspirone","Sertraline alone","CBT alone","Combined CBT and an SSRI"],"answer":4,"why":"Combined CBT plus sertraline had the highest response (80.7%); combination is recommended for severe impairment."},
  {"id":"c2-ax05","tag":"Anxiety","q":"A 5-year-old with separation and social anxiety is too young for standard CBT. Which approach fits?","choices":["Being Brave or the CALM program with parent coaching","DBT","ECT","TF-CBT","Psychoanalysis"],"answer":0,"why":"Being Brave (ages 4–7) and CALM (under 7, PCIT-based live coaching) are designed for young anxious children."},
  {"id":"c2-ax06","tag":"Mutism","q":"A 6-year-old speaks fluently at home (confirmed on video) but has not spoken at school for 2 years, freezing when attention is on her. Hearing and language are normal. What is the diagnosis and first-line treatment?","choices":["Language disorder; speech therapy","ASD; ABA","Selective mutism; CBT with graded speaking exposures and rewards","Normal shyness; no treatment","Conversion disorder; reassurance"],"answer":2,"why":"Normal speech at home but persistent silence at school is selective mutism; CBT is first line for school-age children."},
  {"id":"c2-ax07","tag":"Mutism","q":"A recently immigrated 7-year-old speaks his native language fluently everywhere but is silent in English at school after 2 months. What is most likely?","choices":["Conversion disorder","Selective mutism","Normal reticence while learning a new language","ASD","Social anxiety disorder"],"answer":2,"why":"Selective mutism is diagnosed only if the child refuses the native language too or is competent in the new one but will not use it."},
  {"id":"c2-oc01","tag":"OCD","q":"An 11-year-old washes his hands until they bleed, fears germs will kill his family and insists his rituals make sense. Symptoms are moderate. What is the first-line treatment?","choices":["CBT with exposure and response prevention","Clomipramine","Psychodynamic therapy","Benzodiazepine","Risperidone"],"answer":0,"why":"For mild to moderate pediatric OCD, a trial of CBT (ERP) is recommended before medication; poor insight is common in youth."},
  {"id":"c2-oc02","tag":"OCD","q":"A 14-year-old with severe OCD is housebound by rituals. According to POTS, which approach is best?","choices":["Sertraline plus CBT","CBT alone","Haloperidol","Placebo","Sertraline alone"],"answer":0,"why":"POTS showed combined sertraline and CBT was superior to either alone."},
  {"id":"c2-oc03","tag":"OCD","q":"Parents of a child with OCD answer her reassurance questions dozens of times a day and do her checking for her. Which intervention targets this?","choices":["Hospitalization","Stimulant","More reassurance","Family CBT reducing accommodation","Antipsychotic"],"answer":3,"why":"Family CBT reduces parental involvement and accommodation, which lowers symptoms."},
  {"id":"c2-oc04","tag":"OCD","q":"A 15-year-old has had only partial response to two adequate SSRI trials plus CBT. What is a reasonable next step?","choices":["Add a stimulant","Switch to bupropion","Stop all treatment","Electroconvulsive therapy first","Add an antipsychotic such as aripiprazole or risperidone"],"answer":4,"why":"Antipsychotic augmentation (risperidone; aripiprazole helped 59% after two failed SSRIs) improves partial responders."},
  {"id":"c2-oc05","tag":"OCD","q":"A child develops abrupt OCD and tics 2 weeks after strep throat. Parents ask whether antistreptococcal antibody levels prove the cause. What is accurate?","choices":["Yes, high titers prove PANDAS","No, antigens and antibodies do not establish causation; PANDAS is controversial","Treat with long-term antibiotics as standard","Order an MRI to prove it","OCD is always post-infectious"],"answer":1,"why":"Even with temporal association, streptococcal antigens and antibodies do not indicate a causal relationship."},
  {"id":"c2-sc01","tag":"Schizophrenia","q":"A 7-year-old living with domestic violence briefly reports seeing a shadowy figure and hearing his name called after a frightening night, with normal functioning otherwise. What is most appropriate?","choices":["Diagnose ASD","Order an EEG only","Recognize likely stress-related, self-limited hallucinations; address safety and stress and follow up","Diagnose bipolar disorder","Diagnose schizophrenia and start clozapine"],"answer":2,"why":"Self-limited hallucinations occur in nonpsychotic children under severe stress; schizophrenia requires deterioration or failure to reach expected functioning."},
  {"id":"c2-sc02","tag":"Schizophrenia","q":"A 15-year-old has 8 months of social withdrawal, falling grades, voices commenting on him, and a belief that classmates control his thoughts. Drug screen and labs are normal. Which medication class is first line?","choices":["Clozapine","Lithium","A second-generation antipsychotic such as risperidone or aripiprazole","Benzodiazepine","SSRI alone"],"answer":2,"why":"Second-generation antipsychotics are the mainstay; clozapine is reserved for treatment resistance."},
  {"id":"c2-sc03","tag":"Schizophrenia","q":"A 14-year-old with schizophrenia has not responded to adequate trials of risperidone and olanzapine. What is the evidence-based next step?","choices":["Lithium","Clozapine","Higher-dose risperidone indefinitely","Stop medication","Haloperidol"],"answer":1,"why":"Clozapine outperformed haloperidol and high-dose olanzapine in treatment-resistant early-onset schizophrenia."},
  {"id":"c2-sc04","tag":"APS","q":"A 16-year-old has 2 months of weekly murmuring sounds and fleeting suspiciousness that she recognizes may not be real, with falling grades. What is the safest first treatment?","choices":["Psychological intervention such as CBT with monitoring","Lithium","Stimulant","No treatment","Antipsychotic"],"answer":0,"why":"In attenuated psychosis syndrome, psychological interventions are the safest first choice until better data exist."},
  {"id":"c2-su01","tag":"Substances","q":"A 16-year-old with daily marijuana use and a depressive disorder needs treatment. Which model suits comorbid cases?","choices":["Detention","Random urine testing only","Methadone","Minnesota 12-step model alone","Multidisciplinary professional model with CBT, family therapy and medication"],"answer":4,"why":"The physician-led multidisciplinary model is suited to adolescents with comorbid psychiatric disorders."},
  {"id":"c2-su02","tag":"Substances","q":"Two days after stopping heavy daily marijuana use, a 17-year-old is irritable, sleepless, restless and craving. What is happening and when will it peak?","choices":["Normal adolescence","Cannabis withdrawal; peaks around 2–4 days and fades by 2 weeks","Alcohol withdrawal seizures","Psychosis; peaks at 2 weeks","Opioid withdrawal"],"answer":1,"why":"Cannabis withdrawal starts about 24 hours after last use, peaks at 2–4 days and diminishes after 2 weeks."},
  {"id":"c2-su03","tag":"Substances","q":"A school clinic wants to identify and help students who drink. Which approach has supporting data in the chapter?","choices":["Universal methadone","Lectures only","Random searches","SBIRT with motivational-interviewing brief intervention","Expulsion policy"],"answer":3,"why":"School-based SBIRT reduced drinking to intoxication and drug use at 6 months."}
]);
